# -*- coding: utf-8 -*-
"""دراسة السوق والإعلانات والخطط التسويقية - أدوات متقدمة."""
from biz_tools import F, S, add, CATS, T
OL="function ol(a){return'<ol>'+a.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ol>'}"

add('market-size-tam-sam-som','marketing','🌍','حاسبة حجم السوق TAM/SAM/SOM','قدّر حجم السوق الكلي والمتاح والمستهدف من الأعلى للأسفل ومن الأسفل للأعلى.',
 [F('pop','إجمالي العملاء المحتملين في السوق','n',2000000),F('p','متوسط الإنفاق السنوي للعميل','n',600),F('sam','نسبة ما تخدمه جغرافيًا/شريحيًا %','n',25),F('som','حصة واقعية تحصل عليها %','n',3),F('ch','عملاء تصلهم قنواتك سنويًا (من الأسفل)','n',5000),F('cr','نسبة التحويل %','n',4)],
 r'''function compute(v){const tam=v.pop*v.p,sam=tam*v.sam/100,som=sam*v.som/100,bu=v.ch*v.cr/100*v.p;return kpis([kpi('TAM السوق الكلي',f(tam)),kpi('SAM المتاح',f(sam)),kpi('SOM المستهدف',f(som),'good'),kpi('تقدير من الأسفل للأعلى',f(bu))])+rec([Math.abs(som-bu)/(som||1)>0.5?'الفرق كبير بين المنهجين: راجع فرضياتك قبل عرضها على مستثمر.':'المنهجان متقاربان: تقديرك أكثر إقناعًا.','المستثمرون يفضّلون التقدير من الأسفل للأعلى.'])+aiOut('اكتب قسم حجم السوق في خطة عمل بناءً على: TAM '+f(tam)+' وSAM '+f(sam)+' وSOM '+f(som)+' مع مصادر مقترحة للتحقق.')}''')

add('competitor-matrix','marketing','🥊','مصفوفة تحليل المنافسين','قارن نفسك بمنافسيك بمعايير مرجّحة وحدد فجوات التميز.',
 [F('c','المعايير | الوزن','textarea','السعر | 30\nالجودة | 30\nخدمة العملاء | 20\nالتوصيل | 20',r=4),F('n','أنت | درجات 1-10 بنفس الترتيب','text','أنت | 7,8,6,9'),F('o','المنافسون | الدرجات (سطر لكل منافس)','textarea','منافس أ | 8,7,6,6\nمنافس ب | 6,9,8,7',r=3)],
 r'''function compute(v){const W=lines(v.c).map(r=>num(r[1])),tw=W.reduce((a,b)=>a+b,0)||1,names=lines(v.c).map(r=>r[0]);const sc=r=>String(r[1]).split(',').map(Number);const me=sc(lines(v.n)[0]),all=[[ 'أنت',me]].concat(lines(v.o).map(r=>[r[0],sc(r)]));const tot=s=>s.reduce((a,x,i)=>a+x*(W[i]||0),0)/tw;const rows=all.map(a=>[a[0]].concat(a[1].map(x=>x)).concat([f(tot(a[1]),2)]));let gaps=[];names.forEach((n,i)=>{const best=Math.max(...all.slice(1).map(a=>a[1][i]||0));if(best>me[i])gaps.push(n+' (الأفضل '+best+' مقابل '+me[i]+')')});return tbl(['الجهة'].concat(names).concat(['الإجمالي المرجّح']),rows)+rec([gaps.length?'فجوات تحتاج علاجًا: '+gaps.join('، '):'تتفوق في كل المعايير المدخلة.','ركّز رسالتك التسويقية على معيارك الأقوى وزنًا.'])}''')

add('swot-tows-strategy','marketing','🧭','محوّل SWOT إلى استراتيجيات TOWS','حوّل نقاط القوة والضعف إلى استراتيجيات SO/WO/ST/WT.',
 [F('s','نقاط القوة','textarea','جودة عالية\nفريق خبير',r=3),F('w','نقاط الضعف','textarea','ميزانية محدودة',r=3),F('o','الفرص','textarea','نمو التسوق عبر الجوال',r=3),F('t','التهديدات','textarea','دخول منافسين أجانب',r=3)],
 r'''function compute(v){const L=x=>x.split('\n').map(a=>a.trim()).filter(Boolean);const S=L(v.s),W=L(v.w),O=L(v.o),T=L(v.t);const mk=(a,b,verb)=>a.slice(0,3).flatMap(x=>b.slice(0,2).map(y=>verb+': '+x+' × '+y));return '<h4>SO — استثمر</h4>'+ol(mk(S,O,'استخدم'))+'<h4>WO — عالج</h4>'+ol(mk(W,O,'عالج'))+'<h4>ST — تحصّن</h4>'+ol(mk(S,T,'استخدم'))+'<h4>WT — تجنّب</h4>'+ol(mk(W,T,'قلّل'))+aiOut('حوّل تحليل SWOT التالي إلى 8 استراتيجيات TOWS محددة بمؤشرات قياس. القوة: '+S.join('،')+' الضعف: '+W.join('،')+' الفرص: '+O.join('،')+' التهديدات: '+T.join('،'))}'''+OL)

add('customer-persona-builder','marketing','🧑‍🤝‍🧑','منشئ شخصية العميل Persona','ملف عميل مثالي يوجّه الإعلان والمحتوى.',
 [F('n','اسم الشخصية','text','نورة'),F('a','العمر والمهنة','text','28، موظفة'),F('g','هدفها','text','شراء هدايا مميزة بسرعة'),F('p','ألمها/مشكلتها','text','تأخر التوصيل وعدم الثقة بالمتاجر'),F('c','أين تقضي وقتها','text','سناب، انستغرام'),F('o','اعتراضاتها','text','السعر والإرجاع')],
 r'''function compute(v){return '<div class="kpis">'+kpi('الشخصية',v.n)+kpi('الشريحة',v.a)+'</div>'+ol(['هدفها: '+v.g,'ألمها: '+v.p,'قنواتها: '+v.c,'اعتراضاتها: '+v.o,'رسالة مقترحة: "'+v.g+' — بدون قلق من '+v.p+'"','عرض يزيل الاعتراض: ضمان وسياسة إرجاع واضحة تعالج «'+v.o+'»'])+aiOut('أنشئ Persona مفصّلة للعميل '+v.n+' ('+v.a+') وهدفها '+v.g+' وألمها '+v.p+' وقنواتها '+v.c+' واعتراضاتها '+v.o+' مع 5 رسائل إعلانية.')}'''+OL)

add('marketing-plan-generator','marketing','📘','مولّد خطة تسويقية كاملة','خطة تسويق من الهدف إلى الميزانية والقنوات والمؤشرات.',
 [F('n','النشاط','text','متجر قهوة مختصة أونلاين'),F('g','الهدف الرقمي','text','500 طلب شهريًا'),F('b','الميزانية الشهرية','n',8000),F('a','الجمهور','text','25-40 محبو القهوة'),F('m','المدة (أشهر)','n',3),F('u','ميزة تفرّقك','text','تحميص طازج خلال 48 ساعة')],
 r'''function compute(v){const ch=[['إعلانات سناب/تيك توك',40],['إنستغرام وصناع المحتوى',25],['بحث جوجل',15],['بريد/واتساب للعملاء',10],['محتوى ومقالات',10]];const rows=ch.map(c=>[c[0],c[1]+'%',f(v.b*c[1]/100)]);return tbl(['القناة','النسبة','الميزانية الشهرية'],rows)+'<h4>مراحل الخطة</h4>'+ol(['الشهر 1: بناء الأساس — هوية، صفحة هبوط، تتبع، اختبار 5 إعلانات','الشهر 2: التوسع في الإعلان الأفضل ومضاعفة المحتوى والتعاون مع صانعي محتوى','الشهر 3: تحسين التحويل، حملات إعادة الاستهداف، برنامج ولاء'].slice(0,Math.max(1,Math.min(3,v.m))))+'<h4>المؤشرات</h4>'+ol(['الهدف: '+v.g,'تكلفة الاكتساب CAC','عائد الإعلان ROAS','معدل التحويل','معدل التكرار'])+aiOut('اكتب خطة تسويقية تفصيلية لنشاط '+v.n+' للجمهور '+v.a+' بميزة '+v.u+' لتحقيق '+v.g+' بميزانية '+v.b+' شهريًا لمدة '+v.m+' أشهر، مع تقويم أسبوعي وأفكار إعلانات.')}'''+OL)

add('ad-creative-test-planner','marketing','🧪','مخطط اختبار الإعلانات A/B','حجم العينة والميزانية اللازمة لنتيجة موثوقة.',
 [F('c','معدل التحويل الحالي %','n',2),F('l','أقل تحسن تريد اكتشافه %','n',20),F('cpc','تكلفة النقرة','n',0.8),F('d','عدد النسخ المختبرة','n',2)],
 r'''function compute(v){const p=v.c/100,d=p*v.l/100,n=Math.ceil(16*p*(1-p)/(d*d)),tot=n*v.d,cost=tot*v.cpc;return kpis([kpi('زيارات لكل نسخة',f(n,0)),kpi('إجمالي الزيارات',f(tot,0)),kpi('ميزانية الاختبار',f(cost),'good')])+rec(['لا توقف الاختبار قبل بلوغ العينة.','اختبر متغيرًا واحدًا في كل مرة: العنوان أو الصورة أو العرض.','الصيغة تقريبية عند ثقة 95% وقوة 80%.'])}''')

add('ad-copy-framework-generator','marketing','✍️','مولّد نصوص إعلانية بأطر AIDA/PAS/BAB','ثلاثة نصوص إعلانية لنفس المنتج بأطر مجرّبة.',
 [F('p','المنتج','text','كرسي مكتب طبي'),F('b','الفائدة الرئيسية','text','راحة للظهر طوال اليوم'),F('pn','المشكلة','text','آلام الظهر من الجلوس الطويل'),F('o','العرض','text','خصم 20% وشحن مجاني')],
 r'''function compute(v){const A='انتبه: '+v.pn+'؟\nاهتم: '+v.p+' مصمم لـ'+v.b+'.\nرغبة: آلاف العملاء غيّروا يومهم.\nإجراء: '+v.o+' — اطلبه الآن.';const P='المشكلة: '+v.pn+'.\nتفاقم: مع الوقت تزداد وتؤثر على إنتاجيتك.\nالحل: '+v.p+' — '+v.b+'. '+v.o;const B='قبل: '+v.pn+'.\nبعد: '+v.b+'.\nالجسر: '+v.p+'. '+v.o;return '<h4>AIDA</h4><pre>'+esc(A)+'</pre><h4>PAS</h4><pre>'+esc(P)+'</pre><h4>BAB</h4><pre>'+esc(B)+'</pre>'+aiOut('حسّن النصوص الإعلانية التالية بلهجة سعودية بيضاء مع 5 عناوين بديلة:\n'+A+'\n'+P+'\n'+B)}''')

add('campaign-roi-forecaster','marketing','🔮','متوقّع عائد الحملة الإعلانية','قبل الإنفاق: توقّع الطلبات والربح بسيناريوهات متشائم/متوقع/متفائل.',
 [F('b','ميزانية الحملة','n',10000),F('cpc','تكلفة النقرة','n',0.9),F('cr','معدل التحويل %','n',2.5),F('aov','متوسط قيمة الطلب','n',180),F('m','هامش الربح %','n',35)],
 r'''function compute(v){const sc=[['متشائم',0.7],['متوقع',1],['متفائل',1.3]];const rows=sc.map(s=>{const cl=v.b/v.cpc,o=cl*v.cr/100*s[1],rev=o*v.aov,pr=rev*v.m/100-v.b;return[s[0],f(o,0),f(rev),f(rev/v.b,2)+'x',f(pr)]});return tbl(['السيناريو','الطلبات','الإيراد','ROAS','الربح'],rows)+kpis([kpi('ROAS التعادل',f(100/v.m,2)+'x')])+rec(['إن كان ROAS المتشائم تحت التعادل فابدأ بميزانية اختبار صغيرة.'])}''')

add('keyword-research-organizer','marketing','🔎','منظّم أبحاث الكلمات المفتاحية','صنّف كلماتك حسب النية وأولويتها (حجم/صعوبة).',
 [F('k','الكلمات | بحث شهري | صعوبة 1-100','textarea','شراء قهوة مختصة | 1200 | 35\nأفضل قهوة | 5400 | 70\nقهوة اثيوبية اونلاين | 300 | 20\nطريقة تحضير v60 | 2500 | 40',r=6)],
 r'''function compute(v){const R=lines(v.k).map(r=>{const vol=num(r[1]),d=num(r[2]);const it=/شراء|سعر|اونلاين|أونلاين|متجر|طلب/.test(r[0])?'شرائية':/طريقة|كيف|ما هو|دليل/.test(r[0])?'معلوماتية':'استكشافية';return[r[0],vol,d,it,Math.round(vol/(d+10))]}).sort((a,b)=>b[4]-a[4]);return tbl(['الكلمة','البحث','الصعوبة','النية','الأولوية'],R.map(r=>[r[0],f(r[1],0),r[2],r[3],r[4]]))+rec(['ابدأ بالشرائية ذات الصعوبة المنخفضة.','اكتب مقالًا واحدًا لكل نية معلوماتية واربطه بصفحة المنتج.'])}''')

add('brand-positioning-statement','marketing','📌','صانع بيان التموضع','جملة تموضع تحدد لمن أنت ولماذا تختلف.',
 [F('b','العلامة','text','بن الديرة'),F('t','الجمهور','text','محبي القهوة المختصة'),F('c','الفئة','text','محمصة قهوة'),F('d','الفائدة المميزة','text','تحميص طازج لباب البيت'),F('r','الدليل','text','التحميص قبل الشحن بـ 48 ساعة')],
 r'''function compute(v){const s='لـ'+v.t+'، '+v.b+' هي '+v.c+' التي تقدم '+v.d+'، لأن '+v.r+'.';return '<div class="result"><b>'+esc(s)+'</b></div>'+rec(['اختبر الجملة مع 5 عملاء: هل يفهمون الفرق؟','حوّلها إلى شعار قصير وسطر تعريفي لصفحتك.'])+aiOut('حوّل بيان التموضع التالي إلى 10 شعارات قصيرة وسطر تعريفي: '+s)}''')

add('influencer-cost-roi','marketing','🌟','حاسبة عائد المؤثرين','تكلفة الطلب والعائد من حملة مؤثرين.',
 [F('f','تكلفة المؤثر','n',3000),F('r','وصول متوقع','n',80000),F('e','نسبة التفاعل %','n',3),F('c','نقر إلى الموقع من التفاعل %','n',10),F('cr','تحويل الموقع %','n',3),F('a','متوسط الطلب','n',200)],
 r'''function compute(v){const cl=v.r*v.e/100*v.c/100,o=cl*v.cr/100,rev=o*v.a;return kpis([kpi('نقرات',f(cl,0)),kpi('طلبات',f(o,1)),kpi('الإيراد',f(rev)),kpi('تكلفة الطلب',f(o?v.f/o:0),'bad'),kpi('ROAS',f(rev/v.f,2)+'x',rev>v.f?'good':'bad')])+rec(['اطلب كود خصم خاص بكل مؤثر للتتبع.','ابدأ بمؤثرين صغار (micro) لتجربة أرخص.'])}''')

add('survey-question-builder','marketing','📝','منشئ استبيان دراسة السوق','أسئلة جاهزة لاستبيان يقيس الاحتياج والسعر والنية.',
 [F('p','المنتج/الفكرة','text','تطبيق توصيل صحي'),F('a','الجمهور','text','موظفون 22-45')],
 r'''function compute(v){return ol(['كم مرة '+'تواجه المشكلة المتعلقة بـ'+v.p+'؟ (يوميًا/أسبوعيًا/نادرًا)','كيف تحلّها الآن؟ (سؤال مفتوح)','ما أكثر ما يزعجك في الحل الحالي؟','لو توفر '+v.p+' ما أهم 3 مزايا تريدها؟ (ترتيب)','كم تتوقع أن تدفع شهريًا؟ (نطاقات)','ما السعر الذي تراه غاليًا جدًا؟ وما السعر الذي تشك في جودته لرخصه؟','هل ستجربه في 30 يومًا؟ (1-5)','أين تسمع عن المنتجات الجديدة؟','العمر والمدينة والدخل (اختياري)'])+rec(['وزّع الاستبيان على '+v.a+' فقط.','30 إجابة على الأقل لاستخلاص اتجاه، و100 لثقة أفضل.'])+aiOut('اكتب استبيانًا احترافيًا من 12 سؤالًا لدراسة جدوى '+v.p+' للجمهور '+v.a)}'''+OL)

add('pricing-strategy-advisor','marketing','💲','مستشار استراتيجية التسعير','سعر مقترح من التكلفة والمنافسين وقيمة العميل.',
 [F('c','التكلفة للوحدة','n',60),F('m','هامش مستهدف %','n',50),F('l','أرخص منافس','n',110),F('h','أغلى منافس','n',190),F('v','قيمة المنتج في نظر العميل (تقدير)','n',160)],
 r'''function compute(v){const cp=v.c/(1-v.m/100),mid=(v.l+v.h)/2,rec_=Math.max(cp,Math.min(v.v,mid));return kpis([kpi('سعر بالتكلفة',f(cp)),kpi('وسط السوق',f(mid)),kpi('بالقيمة المدركة',f(v.v)),kpi('المقترح',f(rec_),'good')])+rec([cp>v.h?'تكلفتك تتطلب سعرًا فوق السوق: ميّز المنتج أو خفّض التكلفة.':'تسعيرك ضمن نطاق السوق.','جرّب السعر السيكولوجي (…9 أو …5).','اختبر سعرين لمدة أسبوعين وقارن الأرباح لا الطلبات.'])}''')

add('marketing-funnel-planner','marketing','🧲','مخطط قمع التسويق','من الظهور إلى الشراء: كم تحتاج في كل مرحلة لتحقق هدفك؟',
 [F('g','هدف الطلبات','n',200),F('c1','تحويل الزائر إلى مهتم %','n',20),F('c2','مهتم إلى سلة %','n',25),F('c3','سلة إلى شراء %','n',40),F('cpm','تكلفة 1000 ظهور','n',15),F('ctr','نسبة النقر %','n',1.2)],
 r'''function compute(v){const s=v.g/(v.c3/100),i=s/(v.c2/100),vis=i/(v.c1/100),imp=vis/(v.ctr/100),cost=imp/1000*v.cpm;return tbl(['المرحلة','المطلوب'],[['ظهور',f(imp,0)],['زوار',f(vis,0)],['مهتمون',f(i,0)],['سلال',f(s,0)],['طلبات',f(v.g,0)]])+kpis([kpi('ميزانية الظهور',f(cost),'good'),kpi('تكلفة الطلب',f(cost/v.g))])+rec(['أضعف نسبة تحويل هي أولى مراحل التحسين.'])}''')

add('seasonal-campaign-calendar','marketing','📅','تقويم المواسم والحملات','أهم مواسم البيع في السعودية والخليج وتجهيز كل موسم.',
 [S('m','الشهر الحالي',[(str(i),n) for i,n in enumerate(['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'],1)])],
 r'''function compute(v){const E=[['اليوم الوطني (سبتمبر 23)',9],['يوم التأسيس (فبراير 22)',2],['رمضان والعيد (تتغير سنويًا)',3],['العودة للمدارس (أغسطس/سبتمبر)',8],['الجمعة البيضاء (نوفمبر)',11],['يوم الأم (مارس 21)',3],['الصيف والسفر (يونيو-يوليو)',6],['موسم الشتاء والتخييم (نوفمبر-فبراير)',12]];const m=+v.m,rows=E.map(e=>{const d=(e[1]-m+12)%12;return[e[0],d===0?'هذا الشهر':'بعد '+d+' شهر',d<=1?'جهّز الآن: مخزون، عروض، تصاميم':d<=3?'ابدأ التخطيط والمخزون':'مراقبة']}).sort((a,b)=>a[1].localeCompare(b[1]));return tbl(['الموسم','متى','التجهيز'],rows)+rec(['ابدأ الحملة قبل الموسم بـ 3-4 أسابيع.','تواريخ رمضان والعيد تتغير: تحقق منها سنويًا.'])}''')
